import { PagingMetadata } from './PagingMetadata'
import { WixDataItem } from './types'

export interface WixDataQueryReferencedItemsResponse<Item = WixDataItem> {
  /** Referenced results. For successfully resolved references, the referenced data item is returned. For references that can't be resolved, the unresolved reference is returned. */
  results: ReferencedResult<Item>[]

  /** Paging information. */
  pagingMetadata: PagingMetadata
}

export interface ReferencedResult<Item = WixDataItem> {
  /** ID of the referring item. */
  referringItemId: string

  /** Referenced item. It is present when reference is successfully resolved. */
  item?: Item

  /** Unresolved reference appears instead of the item when the reference doesn't resolve, for example, when an ID isn't found or if an item is in draft state. */
  unresolvedReference?: UnresolvedReference
}

export interface UnresolvedReference {
  /** ID of unresolved referenced item. */
  referencedItemId: string

  /** Flag is set if item exists, but user is not authorized to read it. */
  unauthorized: boolean
}
